def scan_systemd():
    systemd_dirs = [
        '/etc/systemd/system', '/usr/lib/systemd/system', '/run/systemd/system', '/lib/systemd/system'
    ]
    if os.path.exists('/app_target'):
        systemd_dirs.extend([
            '/app_target/etc/systemd/system', '/app_target/usr/lib/systemd/system', '/app_target/run/systemd/system'
        ])

    unit_files = set()
    for d in systemd_dirs:
        if os.path.isdir(d):
