def scan_rc_local():
    rc_files = ['/etc/rc.local', '/etc/rc.d/rc.local']
    if os.path.exists('/app_target'):
        rc_files.extend(['/app_target/etc/rc.local', '/app_target/etc/rc.d/rc.local'])

    for f in set(rc_files):
        if not os.path.isfile(f):
            continue
        try:
            rp = os.path.realpath(f)
            with open(rp, 'rb') as fp:
                data = fp.read()
            h = hashlib.sha256(data).hexdigest()
            lines = data.decode('utf-8', errors='replace').splitlines()
        except Exception:
            continue

        for i, line in enumerate(lines, 1):
            s = line.strip()
            if not s or s.startswith('#'):
                continue
            if s.startswith('exit ') or s == 'exit':
                continue
            artifacts.append({
                'type': 'rc_local',
                'path': rp,
                'sha256': h,
                'details': {
                    'line_number': i,
                    'content_preview': line[:100],
                    'user': None
                }
            })

def scan_ssh_keys():
    key_files = set()
    patterns = [
        '/home/*/.ssh/authorized_keys', '/root/.ssh/authorized_keys'
    ]
    if os.path.exists('/app_target'):
        patterns.extend([
            '/app_target/home/*/.ssh/authorized_keys', '/app_target/root/.ssh/authorized_keys'
        ])

    for pat in patterns:
        for f in glob.glob(pat):
            if os.path.isfile(f):
                key_files.add(os.path.realpath(f))

    # Also search for any authorized_keys under /home, /root, /app_target
    search_dirs = ['/home', '/root']
    if os.path.exists('/app_target'):
        search_dirs.append('/app_target')

    for d in search_dirs:
        if os.path.isdir(d):
            for root_dir, dirs, files in os.walk(d):
                if 'authorized_keys' in files:
                    fp = os.path.join(root_dir, 'authorized_keys')
                    if os.path.isfile(fp):
                        key_files.add(os.path.realpath(fp))

    legit_key_blobs = {'AAAAB3NzaC1yc2EAAAADAQABAAABgQC7vbqajDhA...'}

    for p in key_files:
        try:
            with open(p, 'rb') as fp:
                data = fp.read()
            h = hashlib.sha256(data).hexdigest()
            lines = data.decode('utf-8', errors='replace').splitlines()
        except Exception:
            continue

        user = None
        if '/root/.ssh/' in p:
            user = 'root'
        else:
            m = re.search(r'/home/([^/]+)/\.ssh/', p)
            if m:
                user = m.group(1)

        for i, line in enumerate(lines, 1):
            s = line.strip()
            if not s or s.startswith('#'):
                continue

            # Check public key line
            if any(kt in s for kt in ['ssh-rsa', 'ssh-ed25519', 'ecdsa-sha2-', 'sk-ssh-', 'ssh-dss']):
                is_suspicious = False
                if '/app_target' in p:
                    is_suspicious = True
                elif any(kw in s.lower() for kw in ['attacker', 'malicious', 'backdoor', 'unknown', 'evil', 'hack', 'shell', 'test', 'temp', 'tmp']):
                    is_suspicious = True
                else:
                    # check blob against known legit blobs
                    parts = s.split()
                    if len(parts) >= 2:
                        blob = parts[1]
                        if blob not in legit_key_blobs:
                            is_suspicious = True

                if is_suspicious:
                    artifacts.append({
                        'type': 'ssh_key',
                        'path': p,
                        'sha256': h,
                        'details': {
                            'line_number': i,
                            'content_preview': line[:100],
                            'user': user
                        }
                    })

scan_cron()
scan_systemd()
scan_rc_local()
scan_ssh_keys()

# Sort artifacts: by type, then path, then line_number (or 0 if null)
def sort_key(a):
    ln = a['details']['line_number']
    return (a['type'], a['path'], ln if ln is not None else 0)

artifacts.sort(key=sort_key)

summary = {
    'total_artifacts': len(artifacts),
    'cron_jobs': sum(1 for a in artifacts if a['type'] == 'cron_job'),
    'systemd_units': sum(1 for a in artifacts if a['type'] == 'systemd_unit'),
    'rc_local_modifications': sum(1 for a in artifacts if a['type'] == 'rc_local'),
    'ssh_keys': sum(1 for a in artifacts if a['type'] == 'ssh_key')
}

report = {
    'summary': summary,
    'artifacts': artifacts
}

print(json.dumps(report, indent=2))
